<section class="panel"><div class="panel-head"><div><span class="panel-kicker">محتوى القراء</span><h2>القصص المرسلة</h2><p class="settings-help">راجع النص، أضف ملاحظتك، ثم اختر الإجراء المناسب قبل النشر.</p></div><span><?=count($rows)?> قصة</span></div><div class="story-admin-list"><?php foreach($rows as $r):?><article class="story-admin-card"><div class="story-admin-head"><div><span class="status s-<?=e($r['status'])?>"><?=e($r['status'])?></span><h3><?=e($r['title'])?></h3><small><?=e($r['name'])?> · <?=e($r['email'])?> · <?=e($r['created_at'])?></small></div></div><details><summary>قراءة القصة</summary><div class="story-admin-body"><?=nl2br(e($r['story']))?></div></details><div class="story-admin-actions"><form method="post" action="/admin/story-submissions/update"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><label>الحالة<select name="status"><option value="new" <?=$r['status']==='new'?'selected':''?>>جديدة</option><option value="reviewed" <?=$r['status']==='reviewed'?'selected':''?>>تمت المراجعة</option><option value="accepted" <?=$r['status']==='accepted'?'selected':''?>>مقبولة</option><option value="rejected" <?=$r['status']==='rejected'?'selected':''?>>مرفوضة</option><option value="changes_requested" <?=$r['status']==='changes_requested'?'selected':''?>>طلب تعديل من الكاتب</option></select></label><label>ملاحظة الإدارة<textarea name="admin_note" rows="2"><?=e($r['admin_note']??'')?></textarea></label><div class="story-admin-buttons"><button class="btn btn-primary" type="submit">حفظ التحديث</button><?php if(in_array($r['status'],['accepted','reviewed'],true)):?><button class="btn btn-secondary" type="submit" formaction="/admin/story-submissions/publish" formmethod="post" onclick="return confirm('نشر هذه القصة كمقال؟')">نشر كمقال</button><?php endif;?></div></form><form method="post" action="/admin/story-submissions/delete" onsubmit="return confirm('حذف القصة المرسلة؟')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-danger">حذف</button></form></div></article><?php endforeach;?></div></section>
